+export function Chessground(element: HTMLElement, config?: Config): Api {
+  const maybeState: State | HeadlessState = defaults();
+
+  configure(maybeState, config || {});
+
+  // board-level bindings (like the ResizeObserver) are re-created on every
+  // redraw; keep the unbind of the current generation so the previous one
+  // can be released. document-wide listeners are only bound once.
+  let unbindBoard: cg.Unbind | undefined;
+  let unbindDocument: cg.Unbind | undefined;
+
+  function redrawAll(): State {
+    unbindBoard?.();
+    unbindBoard = undefined;
+
+    // compute bounds from existing board element if possible
+    // this allows non-square boards from CSS to be handled (for 3D)
+    const elements = renderWrap(element, maybeState),
+      bounds = util.memo(() => elements.board.getBoundingClientRect()),
+      redrawNow = (skipSvg?: boolean): void => {
+        render(state);
+        if (elements.autoPieces) autoPieces.render(state, elements.autoPieces);
+        if (!skipSvg && elements.shapes) svg.renderSvg(state, elements);
+      },
+      onResize = (): void => {
+        updateBounds(state);
+        renderResized(state);
+        if (elements.autoPieces) autoPieces.renderResized(state);
+      };
+    const state = maybeState as State;
+    state.dom = {
+      elements,
+      bounds,
+      redraw: debounceRedraw(redrawNow),
+      redrawNow,
+      unbind: () => {
+        unbindBoard?.();
+        unbindDocument?.();
+      },
+    };
+    state.drawable.prevSvgHash = '';
+    updateBounds(state);
+    redrawNow(false);
+    unbindBoard = events.bindBoard(state, onResize);
+    unbindDocument ??= events.bindDocument(state, onResize);
+    state.events.insert?.(elements);
+    return state;
+  }
+
+  return start(redrawAll(), redrawAll);
+}

