// Real-browser verification of demo.html: loads, resizes, RO lifecycle.
// Drives headless Chrome over CDP using Node's built-in fetch/WebSocket.
import { spawn } from 'node:child_process';
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

const CHROME = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const REPO = 'D:/dev/ab-tasks/chessground-qwen-r1';
const PORT = 8471;
const CDP_PORT = 9437;

// --- static server over the repo root (ESM imports fail from file://)
const mime = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.map': 'application/json' };
const server = createServer((req, res) => {
  const file = path.join(REPO, path.normalize(new URL(req.url, 'http://x').pathname).replace(/^[/\\]+/, ''));
  readFile(file).then(
    buf => {
      res.writeHead(200, { 'content-type': mime[path.extname(file)] ?? 'application/octet-stream' });
      res.end(buf);
    },
    () => {
      res.writeHead(404);
      res.end('not found');
    },
  );
});
await new Promise(r => server.listen(PORT, '127.0.0.1', r));

// --- headless Chrome (about:blank first so the RO hook lands before page scripts)
const userDataDir = mkdtempSync(path.join(tmpdir(), 'cg-chrome-'));
const chrome = spawn(
  CHROME,
  [
    '--headless',
    `--remote-debugging-port=${CDP_PORT}`,
    `--user-data-dir=${userDataDir}`,
    '--no-first-run',
    '--no-default-browser-check',
    '--disable-gpu',
    'about:blank',
  ],
  { stdio: 'ignore' },
);

const getJson = p => fetch(`http://127.0.0.1:${CDP_PORT}${p}`).then(r => r.json());
let target;
for (let i = 0; i < 50 && !target; i++) {
  try {
    target = (await getJson('/json/list')).find(t => t.type === 'page');
  } catch {
    /* not up yet */
  }
  if (!target) await new Promise(r => setTimeout(r, 200));
}
if (!target) throw new Error('CDP target not found');

const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => {
  ws.onopen = res;
  ws.onerror = () => rej(new Error('ws connect failed'));
});

let mid = 0;
const pending = new Map();
const events = [];
ws.onmessage = m => {
  const msg = JSON.parse(m.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  } else if (msg.method) events.push(msg);
};
const send = (method, params = {}) =>
  new Promise(res => {
    const id = ++mid;
    pending.set(id, res);
    ws.send(JSON.stringify({ id, method, params }));
  });

// Instrument ResizeObserver before any page script runs: count instances and
// record which ones get disconnected.
const RO_HOOK = `
  window.__ro = { instances: [] };
  const RO = window.ResizeObserver;
  window.ResizeObserver = class extends RO {
    constructor(cb) {
      super(cb);
      this.__disconnected = false;
      window.__ro.instances.push(this);
    }
    disconnect() {
      this.__disconnected = true;
      return super.disconnect();
    }
  };
`;

await send('Page.enable');
await send('Runtime.enable');
await send('Page.addScriptToEvaluateOnNewDocument', { source: RO_HOOK });
const nav = await send('Page.navigate', { url: `http://127.0.0.1:${PORT}/demo.html` });
if (nav.error) throw new Error(`navigate failed: ${JSON.stringify(nav.error)}`);

for (let i = 0; i < 100 && !events.some(e => e.method === 'Page.loadEventFired'); i++)
  await new Promise(r => setTimeout(r, 100));
await new Promise(r => setTimeout(r, 300)); // let the module script settle

// chessground builds <cg-board>/<cg-container> custom tags (not classes).
const PROBE = `(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const out = {};
  out.boards = document.querySelectorAll('cg-board').length;
  out.roOnLoad = window.__ro.instances.length;
  const wrap1 = document.getElementById('board-1');
  const container1 = wrap1.querySelector('cg-container');
  out.widthBefore = container1.style.width;
  wrap1.style.width = '400px';
  wrap1.style.height = '400px';
  await sleep(500);
  out.widthAfter = container1.style.width;
  const { Chessground } = await import('./dist/chessground.js');
  const w = document.createElement('div');
  w.style.cssText = 'width:300px;height:300px';
  document.body.appendChild(w);
  const cg = Chessground(w, {});
  window.__cg = cg;
  out.roAfterNewBoard = window.__ro.instances.length;
  cg.redrawAll();
  cg.redrawAll();
  out.roAfterRedraws = window.__ro.instances.length;
  out.liveAfterRedraws = window.__ro.instances.filter(o => !o.__disconnected).length;
  cg.destroy();
  out.liveAfterDestroy = window.__ro.instances.filter(o => !o.__disconnected).length;
  return out;
})()`;

const r = await send('Runtime.evaluate', { expression: PROBE, awaitPromise: true, returnByValue: true });
if (r.error || r.result.exceptionDetails) {
  for (const e of events)
    if (e.method === 'Runtime.exceptionThrown' || e.method === 'Runtime.consoleAPICalled')
      console.log('PAGE EVENT:', JSON.stringify(e.params.exceptionDetails ?? e.params.args)?.slice(0, 600));
  const diag = await send('Runtime.evaluate', {
    expression:
      "JSON.stringify({ url: location.href, boards: document.querySelectorAll('cg-board').length, board1: !!document.getElementById('board-1'), bodyLen: document.body.innerHTML.length })",
    returnByValue: true,
  });
  console.log('DIAG:', diag.result?.value, 'ERR:', JSON.stringify(diag.error ?? diag.result?.exceptionDetails));
  throw new Error(`probe failed: ${JSON.stringify(r.error ?? r.result.exceptionDetails)}`);
}
console.log(JSON.stringify(r.result.value, null, 2));
const pageErrors = events.filter(e => e.method === 'Runtime.exceptionThrown');
const consoleErrors = events.filter(e => e.method === 'Runtime.consoleAPICalled' && e.params.type === 'error');
console.log(`page exceptions: ${pageErrors.length}, console errors: ${consoleErrors.length}`);
for (const e of [...pageErrors, ...consoleErrors]) console.log(JSON.stringify(e.params.exceptionDetails ?? e.params.args));

ws.close();
chrome.kill();
server.close();

const o = r.result.value;
const expected = {
  boards: 5,
  roOnLoad: 5,
  widthBefore: '500px',
  widthAfter: '400px',
  roAfterNewBoard: 6,
  roAfterRedraws: 8,
  liveAfterRedraws: 6,
  liveAfterDestroy: 5,
};
const bad = Object.entries(expected).filter(([k, v]) => o[k] !== v);
if (bad.length || pageErrors.length || consoleErrors.length) {
  console.error(`FAIL: ${JSON.stringify(bad)}`);
  process.exit(1);
}
console.log('PASS: demo loads, board resizes via ResizeObserver, no RO duplication on redraw, RO disconnected on destroy');

